{
  "morphology_wrong_forms": [
    {
      "wrong_form": "identitys",
      "explanation": "Incorrect pluralization rule applied; words ending in a consonant plus 'y' must change the 'y' to 'i' and add '-es'."
    },
    {
      "wrong_form": "identitae",
      "explanation": "Incorrect Latinate pluralization applied; 'identity' is of Late Latin origin, but does not take a first-declension plural."
    },
    {
      "wrong_form": "identien",
      "explanation": "Incorrect Germanic weak plural suffix applied; English nouns do not form plurals using '-en' unless they are irregular relics like ' oxen'."
    }
  ],
  "l1_audio_confusables": [
    {
      "confusable": "intensity",
      "explanation": "Similar syllable count and stress pattern ('i-DEN-ti-ty' vs 'in-TEN-si-ty'), easily misheard in fast speech."
    },
    {
      "confusable": "dentistry",
      "explanation": "Shares the '-ntist-' phonetic core and final unstressed syllable, leading to acoustic overlap when mumbled."
    },
    {
      "confusable": "entirety",
      "explanation": "Similar vowel sounds and rhythmic cadence at the end of the word (-enty vs -ity)."
    }
  ],
  "collocation_distractors": [
    {
      "distractor": "heavy",
      "explanation": "Learners often mistakenly pair abstract nouns with 'heavy' instead of the correct intensifier 'strong' or 'deep'."
    },
    {
      "confusable": "speedy",
      "explanation": "Semantic mismatch; 'speedy' modifies processes or recovery, not abstract concepts like identity."
    },
    {
      "confusable": "narrow",
      "explanation": "Spatial adjective incorrectly applied to a conceptual entity where 'national' or 'personal' is expected."
    }
  ],
  "collocation_wrong_collocate": {
    "wrong_collocate": "fast",
    "explanation": "'Fast' is a physical speed descriptor and cannot collocate with 'identity' to mean rapid or quick; 'rapid' or 'swift' should be used if referring to shifting characteristics."
  },
  "cloze_distractors": [
    {
      "distractor": "identification",
      "explanation": "While related, 'identification' refers to the action or process of identifying someone, not the distinct character or condition itself."
    },
    {
      "distractor": "identical",
      "explanation": "Grammatically incorrect as this slot requires a noun, but learners confuse the adjective form with the noun."
    },
    {
      "distractor": "ideology",
      "explanation": "Semantic distractor; represents a system of ideas rather than the condition of being a specified person or thing."
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "The police asked for his identities before letting him enter the building.",
      "reason": "Used in the plural when referring to a single individual's official documents or personhood, which requires the singular 'identification' or 'identity'."
    },
    {
      "sentence": "She has a very strong identity for playing the piano.",
      "reason": "Incorrect collocation; 'identity' does not pair with 'for [verb]-ing' to describe a skill or talent."
    },
    {
      "sentence": "The two brothers share the same exact identity.",
      "reason": "Semantic misuse; identical twins share physical traits or appearance, but 'identity' refers to the distinct personality or legal personhood, which remains separate."
    }
  ],
  "spot_incorrect": {
    "sentence": "As a global citizen, protecting your digital identity are crucial in modern society.",
    "planted_error": "are",
    "error_description": "Subject-verb agreement failure: the head noun of the subject phrase is the singular 'identity', which requires the singular verb 'is' instead of 'are'.",
    "corrected_version": "As a global citizen, protecting your digital identity is crucial in modern society."
  },
  "word_family_fake_forms": [
    {
      "fake_form": "identize",
      "explanation": "Plausible verb derivation using the '-ize' suffix, but not a recognized English word."
    },
    {
      "fake_form": "identitude",
      "explanation": "Blends 'identity' with the abstract noun suffix '-tude', sounding like a real psychological term."
    },
    {
      "fake_form": "identically",
      "explanation": "Real word, but used as a distractor for the noun family; the fake noun form derived from it is 'identication'."
    }
  ],
  "particle_candidates": [
    "ga",
    "wo",
    "ni",
    "de"
  ]
}
